void dsky_alarm_cycle_input(apollo_overlay_state *s,dsky_charin_io *io,uint16_t n){static const uint16_t raw[]={0,077777,037777,040000,0100000,0177777,0140000,1},verb[]={0,077777,037777,040000,1,077776};uint16_t cm=(uint16_t)(n>=4096u),kind=(uint16_t)(n%3u),start=cm ? 04161u : 04145u;p66_bias_prepare(s,n);s->words[3]=(uint16_t)((n/16u)%8u*0400u);s->words[4]=kind==1u ? 062000u : (uint16_t)((n/128u)%32u*02000u);s->words[6]=(uint16_t)(s->words[4]|(s->words[3]>>8));s->words[5]=kind==0u ? start : kind==1u ? (cm ? 04675u : 04631u) : (uint16_t)(start+5u);s->words[0]=raw[(n/32u)%8u];s->words[1]=raw[(n/64u)%8u];s->words[2]=raw[(n/128u)%8u];s->words[01041]=verb[(n/8u)%6u];if(kind==1u){s->words[0133]=(uint16_t)(start+5u);s->words[0134]=(uint16_t)((n/256u)%32u*02000u);}s->words[01034]=0;io->control.superbank=(uint16_t)(0100u+(n/256u)%4u*020u);io->control.interrupt_enabled=(uint16_t)((n/128u)%2u);io->channel11=(uint16_t)(n*317u&077777u);io->wrote_channel11=0;}
